"use client";

import { useEffect, useState } from "react";

/**
 * Live server clock (display only). The backend time is read from GET /api/attendance/server-time and then counted
 * forward with the browser's monotonic timer (performance.now), which does NOT follow the laptop / mobile clock —
 * changing the device date or time never changes what is shown. It is re-read every minute, when the tab comes back,
 * and at once when the device clock is seen to jump (changed by hand, or the device woke from sleep).
 * Official attendance times are always generated by the backend.
 */
let baseServer: number | null = null;   // server epoch (ms) at baseMono
let baseMono = 0;                        // performance.now() when baseServer was measured
let status: "syncing" | "synced" | "offline" = "syncing";
let lastSyncMono = -Infinity;
let inflight: Promise<void> | null = null;
const listeners = new Set<() => void>();
const emit = () => listeners.forEach(l => l());
const mono = () => (typeof performance !== "undefined" ? performance.now() : Date.now());

export async function syncServerClock(): Promise<void> {
    if (inflight) return inflight;
    inflight = (async () => {
        try {
            const t0 = mono();
            const r = await fetch("/api/attendance/server-time", { cache: "no-store" });
            const t1 = mono();
            if (!r.ok) throw new Error(String(r.status));
            const d = await r.json();
            const server = Date.parse(d.serverTime);
            if (isNaN(server)) throw new Error("bad time");
            baseServer = server + (t1 - t0) / 2;   // half the round trip
            baseMono = t1;
            status = "synced"; lastSyncMono = t1;
        } catch {
            status = "offline"; lastSyncMono = mono() - 50000; // try again in about 10 s
        } finally { inflight = null; emit(); }
    })();
    return inflight;
}

/** Server time now, or null while it has never been synced (nothing is made up) */
export const serverNow = (): Date | null => (baseServer === null ? null : new Date(baseServer + (mono() - baseMono)));

const IST = "Asia/Kolkata";
/** YYYY-MM-DD in IST */
export const istDate = (d: Date) => d.toLocaleDateString("en-CA", { timeZone: IST });
/** HH:MM (24 h) in IST */
export const istHHMM = (d: Date) => d.toLocaleTimeString("en-GB", { timeZone: IST, hour: "2-digit", minute: "2-digit", hour12: false });
/** HH:MM:SS (24 h) in IST */
export const istHHMMSS = (d: Date) => d.toLocaleTimeString("en-GB", { timeZone: IST, hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
/** "Wednesday, 14 October 2026" (same on every browser) */
export const istLongDate = (d: Date) => {
    const p = Object.fromEntries(new Intl.DateTimeFormat("en-GB", { timeZone: IST, weekday: "long", day: "numeric", month: "long", year: "numeric" })
        .formatToParts(d).map(x => [x.type, x.value]));
    return `${p.weekday}, ${p.day} ${p.month} ${p.year}`;
};
export const istClock = (d: Date, seconds = false) => d.toLocaleTimeString("en-US", { timeZone: IST, hour: "2-digit", minute: "2-digit", ...(seconds ? { second: "2-digit" } : {}), hour12: true });

/** Re-renders every second with the server time; re-syncs every 60 s, when the tab comes back and when the device clock jumps */
export function useServerClock() {
    const [, setTick] = useState(0);
    useEffect(() => {
        const l = () => setTick(t => t + 1);
        listeners.add(l);
        if (baseServer === null || mono() - lastSyncMono > 60000) syncServerClock();
        // device clock jump check: wall clock and monotonic timer must move together
        let lastWall = Date.now(), lastMono = mono();
        const tick = setInterval(() => {
            const w = Date.now(), m = mono();
            const jumped = Math.abs((w - lastWall) - (m - lastMono)) > 5000;
            lastWall = w; lastMono = m;
            if (jumped || m - lastSyncMono > 60000) syncServerClock();
            setTick(t => t + 1);
        }, 1000);
        const vis = () => { if (document.visibilityState === "visible") syncServerClock(); };
        document.addEventListener("visibilitychange", vis);
        window.addEventListener("focus", vis);
        window.addEventListener("online", vis);
        return () => { listeners.delete(l); clearInterval(tick); document.removeEventListener("visibilitychange", vis); window.removeEventListener("focus", vis); window.removeEventListener("online", vis); };
    }, []);
    return { now: serverNow(), status };
}